<?php
session_start();
require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/includes/sample-schema.php';
require_once __DIR__ . '/includes/workflow-nav.php';
date_default_timezone_set('America/Chicago');

function h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function sample_no(): string { return 'LS-' . date('Ymd') . '-' . strtoupper(substr(bin2hex(random_bytes(3)), 0, 6)); }

$pdo = db();
sample_schema_assert($pdo);
$statuses = ['Requested','Preparing','Ready to Ship','Shipped','Delivered','Customer Testing','Approved','Rejected','Follow-Up Needed','Quoted','Ordered','Closed'];
$results = ['','Pending','Approved','Rejected','Needs Another Sample','No Response'];
$units = ['OZ','LB','G','KG','ML','GAL','EA','BAG','PAIL','DRUM','TOTE'];
if (empty($_SESSION['samples_csrf'])) $_SESSION['samples_csrf'] = bin2hex(random_bytes(32));
$csrf = $_SESSION['samples_csrf'];
$message = (string)($_SESSION['sample_message'] ?? ''); unset($_SESSION['sample_message']); $error = '';

$blank = ['id'=>'','sample_number'=>sample_no(),'request_date'=>date('Y-m-d'),'needed_by'=>'','status'=>'Requested','sales_rep'=>'','sales_rep_email'=>'','customer_no'=>'','customer_company'=>'','contact_name'=>'','contact_email'=>'','contact_phone'=>'','ship_to'=>'','product_number'=>'','product_name'=>'','cas_number'=>'','manufacturer'=>'','lot_number'=>'','sample_quantity'=>'','sample_unit'=>'LB','packaging'=>'','application'=>'','currently_buying'=>'','current_supplier'=>'','reason_for_sample'=>'','shipping_method'=>'','carrier'=>'','shipping_account_number'=>'','tracking_number'=>'','shipped_date'=>'','delivered_date'=>'','follow_up_date'=>date('Y-m-d', strtotime('+7 days')),'evaluation_result'=>'','customer_feedback'=>'','internal_notes'=>'','quote_number'=>'','order_number'=>''];
$record = $blank;
if (isset($_GET['resume_preview']) && !empty($_SESSION['sample_preview']) && is_array($_SESSION['sample_preview'])) $record=array_merge($blank,$_SESSION['sample_preview']);

if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
 if (!hash_equals($csrf, (string)($_POST['csrf'] ?? ''))) { $error='Your session expired. Refresh the page and try again.'; }
 else {
  $action = $_POST['action'] ?? 'save';
  if ($action === 'delete') {
   $id=(int)($_POST['id'] ?? 0);
   $stmt=$pdo->prepare('DELETE FROM sample_records WHERE id=?'); $stmt->execute([$id]);
   header('Location: samples.php?deleted=1'); exit;
  }
  $record = array_merge($blank, array_intersect_key($_POST, $blank));
  $record['id']=(int)($_POST['id'] ?? 0);
  if (!in_array($record['status'],$statuses,true)) $record['status']='Requested';
  if (!in_array($record['sample_unit'],$units,true)) $record['sample_unit']='LB';
  if (!in_array($record['evaluation_result'],$results,true)) $record['evaluation_result']='';
  if (trim($record['customer_company'])==='' || trim($record['product_name'])==='') $error='Customer company and product name are required.';
  elseif ($action === 'preview_report') { $_SESSION['sample_preview']=$record; header('Location: samples.php?preview=1'); exit; }
  else {
   $fields=['sample_number','request_date','needed_by','status','sales_rep','sales_rep_email','customer_no','customer_company','contact_name','contact_email','contact_phone','ship_to','product_number','product_name','cas_number','manufacturer','lot_number','sample_quantity','sample_unit','packaging','application','currently_buying','current_supplier','reason_for_sample','shipping_method','carrier','shipping_account_number','tracking_number','shipped_date','delivered_date','follow_up_date','evaluation_result','customer_feedback','internal_notes','quote_number','order_number'];
   foreach (['needed_by','shipped_date','delivered_date','follow_up_date'] as $f) if ($record[$f]==='') $record[$f]=null;
   if ($record['id']) {
    $set=implode(',',array_map(fn($f)=>"$f=:$f",$fields)); $sql="UPDATE sample_records SET $set WHERE id=:id";
   } else {
    $sql='INSERT INTO sample_records ('.implode(',',$fields).') VALUES (:'.implode(',:',$fields).')';
   }
   $params=[]; foreach($fields as $f) $params[":$f"]=$record[$f]; if($record['id'])$params[':id']=$record['id'];
   try {
    $pdo->prepare($sql)->execute($params); $id=$record['id'] ?: (int)$pdo->lastInsertId();
    if ($action === 'save_email') {
     if (!filter_var($record['sales_rep_email'], FILTER_VALIDATE_EMAIL)) throw new RuntimeException('The sample was saved, but it was not emailed because the sales representative email address is missing or invalid.');
     $sendCustomer = isset($_POST['send_customer_report']) && $_POST['send_customer_report'] === '1';
     if ($sendCustomer && !filter_var($record['contact_email'], FILTER_VALIDATE_EMAIL)) throw new RuntimeException('The sample was saved, but the customer report was not emailed because the customer email address is missing or invalid.');
     $sendOrders = isset($_POST['cc_orders']) && $_POST['cc_orders'] === '1';
     $internalTo = $sendOrders ? 'orders@lowechemical.com' : $record['sales_rep_email'];
     $internalCc = $sendOrders ? [$record['sales_rep_email']] : [];
     $subject = preg_replace('/[\r\n]+/', ' ', 'Lowe Chemical Sample Request ' . $record['sample_number'] . ' - ' . $record['product_name']);
     $body = '<html><body style="font-family:Arial,sans-serif;color:#20262d;line-height:1.5">';
     $body .= '<div style="border-top:5px solid #D71920;padding-top:18px"><img src="https://lowechemical.com/images/lowe-logo.png" alt="Lowe Chemical Company" style="max-width:460px;width:100%;height:auto"><h2 style="color:#0B2A5B">Customer Sample Report</h2></div>';
     $body .= '<p><strong>Sample Number:</strong> '.h($record['sample_number']).'<br><strong>Request Date:</strong> '.h($record['request_date']).'<br><strong>Needed By:</strong> '.h($record['needed_by'] ?: 'Not specified').'</p>';
     $body .= '<h3 style="color:#0B2A5B">Customer</h3><p><strong>'.h($record['customer_company']).'</strong><br>'.h($record['contact_name']).'<br>'.nl2br(h($record['ship_to'])).'</p>';
     $body .= '<h3 style="color:#0B2A5B">Sample</h3><p><strong>Product:</strong> '.h($record['product_name']).'<br><strong>Product Number:</strong> '.h($record['product_number']).'<br><strong>CAS Number:</strong> '.h($record['cas_number']).'<br><strong>Quantity:</strong> '.h($record['sample_quantity'].' '.$record['sample_unit']).'<br><strong>Packaging:</strong> '.h($record['packaging']).'<br><strong>Manufacturer / Supplier:</strong> '.h($record['manufacturer']).'</p>';
     if ($record['application']) $body .= '<p><strong>Customer Application:</strong><br>'.nl2br(h($record['application'])).'</p>';
     if ($record['currently_buying']) $body .= '<p><strong>Currently Buying / Sourcing:</strong> '.h($record['currently_buying']).($record['current_supplier'] ? '<br><strong>Current Supplier:</strong> '.h($record['current_supplier']) : '').'</p>';
     if ($record['carrier'] || $record['shipping_account_number']) $body .= '<p><strong>Shipping Company:</strong> '.h($record['carrier']).'<br><strong>Customer Shipping Account:</strong> '.h($record['shipping_account_number']).'</p>';
     if ($record['reason_for_sample']) $body .= '<p><strong>Reason for Sample:</strong><br>'.nl2br(h($record['reason_for_sample'])).'</p>';
     $body .= '<p>Prepared by '.h($record['sales_rep'] ?: 'Lowe Chemical Sales').'</p></body></html>';
     $internalBody = str_replace('</body>', ($record['internal_notes'] ? '<p><strong>Internal Notes:</strong><br>'.nl2br(h($record['internal_notes'])).'</p>' : '').'</body>', $body);
     $headers=['MIME-Version: 1.0','Content-Type: text/html; charset=UTF-8','From: Lowe Chemical Company <sales@lowechemical.com>','Reply-To: '.$record['sales_rep_email']];
     if ($internalCc) $headers[]='Cc: '.implode(', ', $internalCc);
     if (!mail($internalTo, $subject, $internalBody, implode("\r\n", $headers))) throw new RuntimeException('The sample was saved, but the internal sample request email could not be sent.');
     $sentTo=[$internalTo];
     if ($sendCustomer) {
      $customerHeaders=['MIME-Version: 1.0','Content-Type: text/html; charset=UTF-8','From: Lowe Chemical Company <sales@lowechemical.com>','Reply-To: '.$record['sales_rep_email'],'Cc: '.$record['sales_rep_email']];
      if (!mail($record['contact_email'], $subject, $body, implode("\r\n", $customerHeaders))) throw new RuntimeException('The internal request was emailed, but the customer report could not be sent.');
      $sentTo[]=$record['contact_email'];
     }
     $_SESSION['sample_message']='Sample saved and emailed to '.implode(' and ', $sentTo).'. The sales representative was copied.';
    } else $_SESSION['sample_message']='Sample record saved.';
    header('Location: samples.php?report='.$id); exit;
   }
   catch(Throwable $e){ $error=$e->getMessage(); }
  }
 }
}
if ((!empty($_GET['edit']) || !empty($_GET['report'])) && !$error) { $recordId=(int)($_GET['edit'] ?? $_GET['report']);$s=$pdo->prepare('SELECT * FROM sample_records WHERE id=?');$s->execute([$recordId]);$found=$s->fetch();if($found)$record=array_merge($blank,$found); }
if (!empty($_GET['preview']) && !empty($_SESSION['sample_preview']) && is_array($_SESSION['sample_preview'])) $record=array_merge($blank,$_SESSION['sample_preview']);
if (isset($_GET['saved'])) $message='Sample record saved.';
if (isset($_GET['deleted'])) $message='Sample record deleted.';

$q=trim((string)($_GET['q']??'')); $sf=trim((string)($_GET['status']??'')); $where=[];$params=[];
if($q!==''){$where[]='(sample_number LIKE :q OR customer_company LIKE :q OR product_name LIKE :q OR tracking_number LIKE :q OR quote_number LIKE :q OR order_number LIKE :q)';$params[':q']='%'.$q.'%';}
if(in_array($sf,$statuses,true)){$where[]='status=:status';$params[':status']=$sf;}
$sql='SELECT * FROM sample_records '.($where?'WHERE '.implode(' AND ',$where):'').' ORDER BY COALESCE(follow_up_date,\'9999-12-31\'), updated_at DESC LIMIT 300';
$s=$pdo->prepare($sql);$s->execute($params);$records=$s->fetchAll();
$summary=$pdo->query("SELECT COUNT(*) total, SUM(status IN ('Requested','Preparing','Ready to Ship')) pending, SUM(status IN ('Shipped','Delivered','Customer Testing','Follow-Up Needed')) active, SUM(status='Approved') approved, SUM(status IN ('Quoted','Ordered')) converted FROM sample_records")->fetch();
if ((!empty($_GET['report']) && !empty($record['id'])) || (!empty($_GET['preview']) && !empty($_SESSION['sample_preview']))):
?>
