pplier</label><input name="current_supplier" value="<?=h($record['current_supplier'])?>"></div><div class="field span2"><label>Reason for Sample</label><textarea name="reason_for_sample" placeholder="Trial, alternate source, new formulation, quality approval..."><?=h($record['reason_for_sample'])?></textarea></div></div></section>
<section class="card"><h2>Shipping and Follow-Up</h2><div class="grid"><div class="field"><label>Shipping Method</label><input name="shipping_method" placeholder="UPS Ground, FedEx, LTL, sales rep delivery..." value="<?=h($record['shipping_method'])?>"></div><div class="field"><label>Carrier</label><input name="carrier" value="<?=h($record['carrier'])?>"></div><div class="field"><label>Customer Shipping Account</label><input name="shipping_account_number" value="<?=h($record['shipping_account_number'])?>"></div><div class="field"><label>Tracking Number</label><input name="tracking_number" value="<?=h($record['tracking_number'])?>"></div><div class="field"><label>Shipped Date</label><input type="date" name="shipped_date" value="<?=h($record['shipped_date'])?>"></div><div class="field"><label>Delivered Date</label><input type="date" name="delivered_date" value="<?=h($record['delivered_date'])?>"></div><div class="field"><label>Follow-Up Date</label><input type="date" name="follow_up_date" value="<?=h($record['follow_up_date'])?>"></div><div class="field"><label>Evaluation Result</label><select name="evaluation_result"><?php foreach($results as $v):?><option value="<?=h($v)?>" <?=$record['evaluation_result']===$v?'selected':''?>><?=h($v?:'Select...')?></option><?php endforeach;?></select></div><div class="field span2"><label>Customer Feedback</label><textarea name="customer_feedback"><?=h($record['customer_feedback'])?></textarea></div><div class="field span2"><label>Internal Notes</label><textarea name="internal_notes"><?=h($record['internal_notes'])?></textarea></div></div></section>
<section class="card"><h2>Quote and Order Conversion</h2><div class="grid"><div class="field span2"><label>Linked Quote Number</label><input name="quote_number" placeholder="Example: LC-20260915-ABC123" value="<?=h($record['quote_number'])?>"></div><div class="field span2"><label>Order Number</label><input name="order_number" placeholder="Enter after the sample becomes an order" value="<?=h($record['order_number'])?>"></div></div><p class="sub">These fields preserve the connection from sample to quote to completed order. Direct conversion buttons can be added in the next phase.</p></section>
