<div class="actions" style="margin-bottom:20px"><button class="btn" type="submit" name="action" value="preview_report">Preview Sample Report</button><button class="btn primary" type="submit" name="action" value="save"><?= $record['id']?'Update Sample':'Save Sample Only'?></button><button class="btn green" type="submit" name="action" value="save_email"><?= $record['id']?'Update & Email Sample Request':'Save & Email Sample Request'?></button><a class="btn" href="samples.php">Clear / New Sample</a><?php if($record['id']):?><button class="btn danger" type="submit" name="action" value="delete" formnovalidate onclick="return confirm('Delete sample <?=h($record['sample_number'])?>? This cannot be undone.')">Delete Sample</button><?php endif;?></div></form>
<section class="card" id="sampleTracking" hidden><h2>Sample Tracking</h2><form class="filters" method="get"><input name="q" value="<?=h($q)?>" placeholder="Search sample, customer, product, tracking, quote, or order"><select name="status"><option value="">All statuses</option><?php foreach($statuses as $v):?><option <?=$sf===$v?'selected':''?>><?=h($v)?></option><?php endforeach;?></select><button class="btn primary">Search</button></form><div class="table-wrap"><table class="list"><thead><tr><th>Sample</th><th>Customer</th><th>Product</th><th>Status</th><th>Shipping</th><th>Follow-Up</th><th>Quote / Order</th><th></th></tr></thead><tbody><?php if(!$records):?><tr><td colspan="8">No sample records found.</td></tr><?php endif;?><?php foreach($records as $r):?><tr><td><strong><?=h($r['sample_number'])?></strong><div class="sub"><?=h(date('M j, Y',strtotime($r['request_date'])))?> · <?=h($r['sales_rep'])?></div></td><td><strong><?=h($r['customer_company'])?></strong><div class="sub"><?=h($r['contact_name'])?></div></td><td><strong><?=h($r['product_name'])?></strong><div class="sub"><?=h($r['sample_quantity'].' '.$r['sample_unit'].' · '.$r['packaging'])?></div></td><td class="status"><?=h($r['status'])?><div class="sub"><?=h($r['evaluation_result'])?></div></td><td><?=h($r['carrier'])?><div class="sub"><?=h($r['tracking_number'])?></div></td><td class="<?=($r['follow_up_date']&&$r['follow_up_date']<date('Y-m-d')&&!in_array($r['status'],['Ordered','Closed']))?'late':''?>"><?=h($r['follow_up_date']?date('M j, Y',strtotime($r['follow_up_date'])):'-')?></td><td><?php if($r['quote_number']):?><a href="pricequote.php?load=<?=urlencode($r['quote_number'])?>"><?=h($r['quote_number'])?></a><?php else:?>-<?php endif;?><div class="sub"><?=h($r['order_number'])?></div></td><td><div class="actions"><a class="btn" href="samples.php?report=<?=(int)$r['id']?>">View Report</a><a class="btn primary" href="samples.php?edit=<?=(int)$r['id']?>">Open / Edit</a></div></td></tr><?php endforeach;?></tbody></table></div></section></main>
<script>
function device(mode){document.body.dataset.device=mode;document.getElementById('device').classList.add('hide');try{sessionStorage.setItem('sampleDevice',mode)}catch(e){}}
try{const d=sessionStorage.getItem('sampleDevice');if(d)device(d)}catch(e){}
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function json(url){const r=await fetch(url);if(!r.ok)throw new Error('Database search unavailable');return r.json()}
function wireSearch(inputId,resultsId,url,render,choose){const input=document.getElementById(inputId),box=document.getElementById(resultsId);let timer;input.addEventListener('input',()=>{clearTimeout(timer);const q=input.value.trim();if(!q){box.classList.remove('open');return}timer=setTimeout(async()=>{try{const data=await json(url+encodeURIComponent(q));const rows=data.results||[];box.innerHTML=rows.map((x,i)=>`<button type="button" class="result" data-i="${i}">${render(x)}</button>`).join('')||'<div class="result">No matches found</div>';box.classList.add('open');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{choose(rows[+b.dataset.i]);box.classList.remove('open')})}catch(e){box.innerHTML='<div class="result">Search unavailable. Enter manually.</div>';box.classList.add('open')}},200)})}
wireSearch('customerSearch','customerResults','api/customer_search.php?q=',c=>`<strong>${esc(c.customer_name)}</strong><small>${esc(c.customer_no)} · ${esc([c.city,c.state,c.zipcode].filter(Boolean).join(', '))}</small>`,c=>{document.getElementById('customerNo').value=c.customer_no||'';document.getElementById('company').value=c.customer_name||'';document.getElementById('customerSearch').value=c.customer_name||'';document.getElementById('shipTo').value=[c.address,[c.city,c.state,c.zipcode].filter(Boolean).join(', ')].filter(Boolean).join('\n')});
wireSearch('productSearch','productResults','api/product_search.php?q=',p=>`<strong>${esc(p.product_description||p.history_product_name)}</strong><small>${esc(p.product_number)} · ${esc(p.container||'')}</small>`,p=>{document.getElementById('productNo').value=p.product_number||'';document.getElementById('productName').value=p.product_description||p.history_product_name||'';document.getElementById('productSearch').value=document.getElementById('productName').value});
wireSearch('repSearch','repResults','api/rep_search.php?q=',r=>`<strong>${esc(r.name||r.sales_rep)}</strong><small>${esc(r.email||'')}</small>`,r=>{document.getElementById('repSearch').value=r.name||r.sales_rep||'';document.getElementById('repEmail').value=r.email||''});
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))document.querySelectorAll('.results').forEach(x=>x.classList.remove('open'))});
</script></body></html>
